function getCookie(name) { let value = '; ' + document.cookie; let parts = value.split('; ' + name + '='); if (parts.length === 2) return parts.pop().split(';').shift(); return null; } function setCookie(name, value, days) { let expires = ''; if (days) { let date = new Date(); date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000)); expires = '; expires=' + date.toUTCString(); } document.cookie = name + '=' + (value || '') + expires + '; path=/'; } function acceptCookies() { setCookie('cookieConsent', 'accepted', 365); document.getElementById('privacy-consent').style.display = 'none'; } function declineCookies() { setCookie('cookieConsent', 'declined', 365); document.getElementById('privacy-consent').style.display = 'none'; } function showCookieConsent() { if (!getCookie('cookieConsent')) { document.getElementById('privacy-consent').style.display = 'block'; } } if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', showCookieConsent); } else { showCookieConsent(); }